class BowlingGame:
    def __init__(self):
        self._rolls = []
        self._game_over = False

    def roll(self, pins):
        if pins < 0:
            raise ValueError("cannot roll for negative pins")
        if pins > 10:
            raise ValueError("cannot roll for more than 10 pins")

        # Validate frame constraints before adding
        self._validate_roll(pins)
        self._rolls.append(pins)

    def score(self):
        if not self._is_game_complete():
            raise Exception("score cannot be taken until the end of the game")
        return self._calculate_score()

    def _is_game_complete(self):
        """Check if the game is complete and scoreable."""
        rolls = self._rolls
        idx = 0
        frame = 0

        while frame < 10:
            if idx >= len(rolls):
                return False
            if rolls[idx] == 10:
                # Strike: frame advances by 1
                idx += 1
                frame += 1
            else:
                # Open frame: needs two rolls
                if idx + 1 >= len(rolls):
                    return False
                if rolls[idx] + rolls[idx + 1] > 10:
                    return False
                idx += 2
                frame += 1

        # 10th frame special handling
        if frame == 10:
            # Check if 10th frame is complete
            # Find where 10th frame starts
            idx = 0
            frame = 0
            while frame < 9:
                if rolls[idx] == 10:
                    idx += 1
                else:
                    idx += 2
                frame += 1

            # Now idx points to 10th frame
            if idx >= len(rolls):
                return False

            # 10th frame first roll
            first = rolls[idx]
            if first == 10:
                # Strike: need two more rolls
                if idx + 2 >= len(rolls):
                    return False
                # Second and third rolls
                second = rolls[idx + 1]
                third = rolls[idx + 2]
                # If second is not a strike, third can't exceed 10
                if second < 10 and second + third > 10:
                    return False
                return True
            else:
                # Not a strike: need second roll
                if idx + 1 >= len(rolls):
                    return False
                second = rolls[idx + 1]
                if first + second > 10:
                    return False
                # If spare (first + second == 10), need one more fill ball
                if first + second == 10:
                    if idx + 2 >= len(rolls):
                        return False
                    return True
                else:
                    # Open frame in 10th
                    return True

        return False

    def _calculate_score(self):
        rolls = self._rolls
        score = 0
        idx = 0

        for frame in range(10):
            if idx >= len(rolls):
                break

            if rolls[idx] == 10:
                # Strike
                score += 10
                score += rolls[idx + 1] + rolls[idx + 2]
                idx += 1
            elif rolls[idx] + rolls[idx + 1] == 10:
                # Spare
                score += 10
                score += rolls[idx + 2]
                idx += 2
            else:
                # Open frame
                score += rolls[idx] + rolls[idx + 1]
                idx += 2

        return score

    def _validate_roll(self, pins):
        """Validate that a roll is legal given current state."""
        rolls = self._rolls

